def differentiate(polynomial, x):
    terms = []
    i = 0
    while i < len(polynomial):
        sign = 1
        if polynomial[i] == '-':
            sign = -1
            i += 1
        elif polynomial[i] == '+':
            i += 1

        coeff = 0
        while i < len(polynomial) and polynomial[i].isdigit():
            coeff = coeff * 10 + int(polynomial[i])
            i += 1
        if coeff == 0:
            coeff = sign
        else:
            coeff *= sign

        exp = 0
        if i < len(polynomial) and polynomial[i] == 'x':
            i += 1
            if i < len(polynomial) and polynomial[i] == '^':
                i += 1
                while i < len(polynomial) and polynomial[i].isdigit():
                    exp = exp * 10 + int(polynomial[i])
                    i += 1
            else:
                exp = 1
        terms.append((coeff, exp))

    result = sum(coeff * exp * x ** (exp - 1) for coeff, exp in terms)
    return result
